  const store = sampleStore({
    holds: [
      hold({ id: 'hold_a', member: BEN, placedOn: '2026-10-01', status: 'ready', readyOn: '2026-11-02' }),
      hold({ id: 'hold_b', member: CY, placedOn: '2026-10-02', status: 'ready', readyOn: '2026-11-24' }),
